```sql
CREATE OR REPLACE VIEW rec AS SELECT w.work_id, CASE WHEN w.version_of IS NOT NULL AND w.version_of IN (SELECT work_id FROM works) THEN w.version_of ELSE w.work_id END canon, w.year, w.type, w.source_id FROM works w LEFT JOIN sources s USING(source_id) WHERE w.record_source<>'STG' AND w.is_retracted<>'true' AND w.type IN ('ART','REV','SUP','PPR') AND coalesce(s.tier,'')<>'K0';
```
```sql
CREATE OR REPLACE VIEW cred AS SELECT a.work_id, a.author_id, coalesce(au.orcid,a.author_id) person, a.institution_id FROM authorships a JOIN authors au USING(author_id) QUALIFY cast(a.affil_seq as int)=max(cast(a.affil_seq as int)) OVER (PARTITION BY a.work_id,a.author_id);
```
```sql
CREATE OR REPLACE VIEW anc AS WITH RECURSIVE r(inst,anc) AS (SELECT institution_id,institution_id FROM institutions UNION ALL SELECT r.inst,i.parent_id FROM r JOIN institutions c ON c.institution_id=r.anc JOIN institutions i ON i.institution_id=c.parent_id WHERE c.parent_id IS NOT NULL AND c.type<>'AFF') SELECT * FROM r;
```
