```sql
SELECT anc, count(distinct canon) n FROM cred c JOIN rec r USING(work_id) JOIN anc a ON a.inst=c.institution_id WHERE anc IN ('I01','I02','I07','I08','I14','I06','I04','I09') GROUP BY anc ORDER BY anc;
```
